index 0000000..ce7bc24
--- /dev/null
+++ b/internal/server/routes_redirect_test.go
@@ -0,0 +1,209 @@
+package server_test
+
+import (
+	"bytes"
+	"encoding/json"
+	"io"
+	"net/http"
+	"testing"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort4/linkshort4/internal/store"
+)
+
+func signupAndCreateLink(t *testing.T, srvURL string) (string, *http.Cookie) {
+	t.Helper()
+	client := &http.Client{}
+
+	body := bytes.NewReader([]byte(`{"email":"redirect@example.com","password":"1234567890"}`))
+	req, err := http.NewRequest("POST", srvURL+"/api/signup", body)
+	if err != nil {
+		t.Fatal(err)
+	}
+	req.Header.Set("Content-Type", "application/json")
+	res, err := client.Do(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusCreated {
+		t.Fatalf("signup: status %d, want 201", res.StatusCode)
+	}
+	var sessionCookie *http.Cookie
+	for _, c := range res.Cookies() {
+		if c.Name == "session" {
+			sessionCookie = c
+			break
+		}
+	}
+	if sessionCookie == nil {
+		t.Fatal("signup did not set session cookie")
+	}
+
+	linkBody := bytes.NewReader([]byte(`{"url":"https://example.com/target","slug":"test-slug"}`))
+	linkReq, err := http.NewRequest("POST", srvURL+"/api/links", linkBody)
+	if err != nil {
+		t.Fatal(err)
+	}
+	linkReq.Header.Set("Content-Type", "application/json")
+	linkReq.AddCookie(sessionCookie)
+	linkRes, err := client.Do(linkReq)
+	if err != nil {
+		t.Fatal(err)
+	}
+	linkB, _ := io.ReadAll(linkRes.Body)
+	_ = linkRes.Body.Close()
+	if linkRes.StatusCode != http.StatusCreated {
+		t.Fatalf("create link: status %d, want 201; body: %s", linkRes.StatusCode, linkB)
+	}
+	return "test-slug", sessionCookie
+}
+
+func TestRedirect(t *testing.T) {
+	srv, _ := newTestServer(t)
+	slug, _ := signupAndCreateLink(t, srv.URL)
+
+	client := &http.Client{
+		CheckRedirect: func(req *http.Request, via []*http.Request) error {
+			return http.ErrUseLastResponse
+		},
+	}
+	res, err := client.Get(srv.URL + "/" + slug)
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusFound {
+		t.Errorf("GET /%s: status %d, want 302", slug, res.StatusCode)
+	}
+	loc := res.Header.Get("Location")
+	if loc != "https://example.com/target" {
+		t.Errorf("GET /%s: Location = %q, want https://example.com/target", slug, loc)
+	}
+}
+
+func TestRedirectUnknownSlug(t *testing.T) {
+	srv, _ := newTestServer(t)
+	client := &http.Client{
+		CheckRedirect: func(req *http.Request, via []*http.Request) error {
+			return http.ErrUseLastResponse
+		},
+	}
+	res, err := client.Get(srv.URL + "/nonexistent-slug")
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusNotFound {
+		t.Errorf("GET /nonexistent-slug: status %d, want 404", res.StatusCode)
+	}
+}
+
+func TestStats(t *testing.T) {
+	srv, _ := newTestServer(t)
+	slug, sessionCookie := signupAndCreateLink(t, srv.URL)
+
+	client := &http.Client{
+		CheckRedirect: func(req *http.Request, via []*http.Request) error {
+			return http.ErrUseLastResponse
+		},
+	}
+	for i := 0; i < 2; i++ {
+		res, err := client.Get(srv.URL + "/" + slug)
+		if err != nil {
+			t.Fatal(err)
+		}
+		_ = res.Body.Close()
+		if res.StatusCode != http.StatusFound {
+			t.Fatalf("redirect %d: status %d, want 302", i+1, res.StatusCode)
+		}
+	}
+
+	statsReq, err := http.NewRequest("GET", srv.URL+"/api/links/"+slug+"/stats", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	statsReq.AddCookie(sessionCookie)
+	statsRes, err := client.Do(statsReq)
+	if err != nil {
+		t.Fatal(err)
+	}
+	statsB, _ := io.ReadAll(statsRes.Body)
+	_ = statsRes.Body.Close()
+	if statsRes.StatusCode != http.StatusOK {
+		t.Fatalf("GET stats: status %d, want 200; body: %s", statsRes.StatusCode, statsB)
+	}
+	var stats []store.ClickStats
+	if err := json.Unmarshal(statsB, &stats); err != nil {
+		t.Fatalf("unmarshal stats: %v", err)
+	}
+	if len(stats) != 30 {
+		t.Fatalf("stats length = %d, want 30", len(stats))
+	}
+	today := time.Now().UTC().Format("2006-01-02")
+	found := false
+	for _, s := range stats {
+		if s.Date == today {
+			found = true
+			if s.Count != 2 {
+				t.Errorf("today count = %d, want 2", s.Count)
+			}
+			break
+		}
+	}
+	if !found {
+		t.Errorf("today (%s) not found in stats", today)
+	}
+}
+
+func TestStatsUnauthorized(t *testing.T) {
+	srv, _ := newTestServer(t)
+	_, _ = signupAndCreateLink(t, srv.URL)
+
+	res, err := http.Get(srv.URL + "/api/links/test-slug/stats")
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusUnauthorized {
+		t.Errorf("GET stats unauthenticated: status %d, want 401", res.StatusCode)
+	}
+}
+
+func TestStatsOtherUser(t *testing.T) {
+	srv, _ := newTestServer(t)
+	_, _ = signupAndCreateLink(t, srv.URL)
+
+	body := bytes.NewReader([]byte(`{"email":"other@example.com","password":"1234567890"}`))
+	req, err := http.NewRequest("POST", srv.URL+"/api/signup", body)
+	if err != nil {
+		t.Fatal(err)
+	}
+	req.Header.Set("Content-Type", "application/json")
+	res, err := http.DefaultClient.Do(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = res.Body.Close()
+	var otherCookie *http.Cookie
+	for _, c := range res.Cookies() {
+		if c.Name == "session" {
+			otherCookie = c
+			break
+		}
+	}
+
+	statsReq, err := http.NewRequest("GET", srv.URL+"/api/links/test-slug/stats", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	statsReq.AddCookie(otherCookie)
+	statsRes, err := http.DefaultClient.Do(statsReq)
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = statsRes.Body.Close()
+	if statsRes.StatusCode != http.StatusNotFound {
+		t.Errorf("GET stats other user: status %d, want 404", statsRes.StatusCode)
+	}
+}
